INSERT INTO products (id, name, seo_name, brand_id, category_id, specifications, description, status, created_by) VALUES
    ('01a119fe-8e0c-7ea2-9a2c-d11b3d435fe8', 'Mainboard Asus TUF GAMING B550M-PLUS WIFI II', 'mainboard-asus-tuf-gaming-b550m-plus-wifi-ii', '01a119fe-8dde-71a7-aec0-24231bece465', '01a119fe-8dd1-7e4b-a610-a0a6e479d292', '{"Model": "TUF GAMING B550M-PLUS WIFI II", "CPU hỗ trợ": "AMD", "Chipset": "B550", "RAM hỗ trợ": "4 x DIMM, Max. 128GB, DDR4 4866(OC)/4800(OC)/4600(OC)/4466(OC)/4400(OC)/4333(OC)/4266(OC)/4200(OC)/4133(OC)/4000(OC)/3866(OC)/3733(OC)/3600(OC)/3466(OC)/3400(OC)/3333(OC)/3200/3000/2933/2800/2666/2400/2133, Un-buffered Memory*", "Khe cắm mở rộng": "AMD Ryzen™ 5000 Series/ 3000 Series Desktop Processors1 x PCIe 4.0 x16 slot (supports x16 mode)*AMD Ryzen™ 5000 G-Series/ 4000 G-Series Desktop Processors1 x PCIe 3.0 x16 slot (supports x16 mode)*AMD B550 Chipset1 x PCIe 3.0 x16 slot (supports x4 mode)**1 x PCIe 3.0 x1 slot**", "Ổ cứng hỗ trợ": "Supports 2 x M.2 slots and 4 x SATA 6Gb/s portsAMD Ryzen™ 5000 Series/ 3000 Series Desktop ProcessorsM.2_1 slot (Key M), type 2242/2260/2280 (supports PCIe 4.0 x4 & SATA modes)AMD Ryzen™ 5000 G-Series/ 4000 G-Series Desktop ProcessorsM.2_1 slot (Key M), type 2242/2260/2280 (supports PCIe 3.0 x4 & SATA modes)AMD B550 ChipsetM.2_2 slot (Key M), type 2242/2260/2280/22110 (supports PCIe 3.0 x4 & SATA modes)4 x SATA 6Gb/s ports", "Cổng kết nối (Internal)": "Fan and Cooling related1 x 4-pin CPU Fan header1 x 4-pin CPU OPT Fan header2 x 4-pin Chassis Fan headersPower related1 x 24-pin Main Power connector1 x 8-pin +12V Power connectorStorage related2 x M.2 slots (Key M)4 x SATA 6Gb/s portsUSB1 x USB 3.2 Gen 1 header supports additional 2 USB 3.2 Gen 1 ports2 x USB 2.0 headers support additional 4 USB 2.0 portsMiscellaneous1 x Addressable Gen 2 header2 x AURA RGB headers1 x Clear CMOS header1 x COM Port header1 x Front Panel Audio header (AAFP)1 x Speaker header1 x SPI TPM header (14-1pin)1 x 10-1 pin System Panel header", "Cổng kết nối (Back Panel)": "2 x USB 3.2 Gen 2 ports (1 x Type-A + 1 x USB Type-C®)4 x USB 3.2 Gen 1 ports (4 x Type-A, one port can be switched to USB BIOS FlashBack™)2 x USB 2.0 ports (2 x Type-A)1 x DisplayPort1 x HDMI® port1 x Wi-Fi Module1 x Realtek 2.5Gb Ethernet port5 x Audio jacks1 x Optical S/PDIF out port1 x BIOS FlashBack™ button1 x PS/2 Keyboard/Mouse combo port", "LAN / Wireless": "2x2 Wi-Fi 6 (802.11 a/b/g/n/ac/ax) + BT5.2", "Kích cỡ": "microATX24.4cm x 24.4cm"}'::jsonb, 'Sản phẩm Mainboard Asus TUF GAMING B550M-PLUS WIFI II. Tham khảo chi tiết thông số kỹ thuật bên dưới.', 'ACTIVE', '018f0000-0000-7000-8000-000000000001'),
    ('01a119fe-8e0c-7977-af93-7effa02359d1', 'Mainboard GIGABYTE Z890M AORUS ELITE WIFI7 ICE', 'mainboard-gigabyte-z890m-aorus-elite-wifi7-ice', '01a119fe-8de0-70c4-8e69-3cbbf5a6f7f4', '01a119fe-8dd1-7e4b-a610-a0a6e479d292', '{"CPU": "Socket LGA1851: Hỗ trợ cho Bộ xử lý Intel® Core™ UltraBộ nhớ đệm L3 thay đổi tùy theo CPU* Vui lòng tham khảo \"Danh sách hỗ trợ CPU\" để biết thêm thông tin.", "Chipset": "Intel® Z890 Express Chipset", "Bộ nhớ": "Hỗ trợ cho DDR5 8800(OC) /8600(OC) / 8400(OC) /8266(OC) / 8200(OC) / 8000(OC) / 7950(OC) / 7900(OC) / 7800(OC) / 7600(OC) / 7400(OC) / 7200(OC) / 7000(OC) / 6800(OC) / 6600(OC) / 6400 / 6200 / 6000 / 5800 / 5600MT/s.Hỗ trợ các mô-đun bộ nhớ DDR5 6400/5600 MT/s4 ổ cắm DDR5 DIMM hỗ trợ tối đa 256 GB (dung lượng DIMM đơn 64 GB) bộ nhớ hệ thốngKiến trúc bộ nhớ kênh đôiHỗ trợ các mô-đun bộ nhớ ECC Un-buffered DIMM 1Rx8/2Rx8 (hoạt động ở chế độ không phải ECC)Hỗ trợ các mô-đun bộ nhớ Non-ECC Un-buffered DIMM 1Rx8/2Rx8/1Rx16Hỗ trợ các mô-đun bộ nhớ Extreme Memory Profile (XMP)(Cấu hình CPU và bộ nhớ có thể ảnh hưởng đến các loại bộ nhớ, tốc độ dữ liệu và số lượng mô-đun DRAM được hỗ trợ, vui lòng tham khảo \"Danh sách hỗ trợ bộ nhớ\" để biết thêm thông tin.)", "Đồ họa tích hợp": "Bộ xử lý đồ họa tích hợp - Intel® HD Graphics hỗ trợ:- 2 x đầu nối Intel® Thunderbolt™ 4 (cổng USB4® USB Type-C®), hỗ trợ đầu ra video DisplayPort và Thunderbolt™Khi lắp màn hình Thunderbolt™, độ phân giải tối đa được hỗ trợ là 5120x2880@60 Hz với 24 bpp (đầu ra màn hình đơn).Khi lắp màn hình USB4® USB Type-C®, độ phân giải tối đa được hỗ trợ là 3840x2160@240 Hz (đầu ra màn hình đơn).* Do tài nguyên I/O hạn chế của kiến ​​trúc PC, số lượng thiết bị Thunderbolt™ có thể sử dụng phụ thuộc vào số lượng thiết bị PCI Express đang lắp. (Tham khảo Chương 2-6, \"Đầu nối bảng điều khiển phía sau\" để biết thêm thông tin.)* Hỗ trợ phiên bản DisplayPort 1.4 và HDCP 2.3Bộ xử lý đồ họa tích hợp - Hỗ trợ đồ họa Intel® HD:- 1 cổng USB4® USB Type-C®, hỗ trợ đầu ra video USB4 và DisplayPort và độ phân giải tối đa 3840x2160@144 Hz* Hỗ trợ cho phiên bản DisplayPort 2.1- 1 x DisplayPort, hỗ trợ độ phân giải tối đa 3840x2160@144 Hz* Hỗ trợ cho phiên bản DisplayPort 2.1- 1 cổng HDMI phía trước, hỗ trợ độ phân giải tối đa 1920x1080@30 Hz* Hỗ trợ phiên bản HDMI 1.4(Thông số kỹ thuật đồ họa có thể thay đổi tùy thuộc vào hỗ trợ CPU.)Hỗ trợ tối đa 3 màn hình cùng lúc", "Audio": "Realtek® Audio CODECÂm thanh độ nét cao2/4/5.1/7.1 kênh* Bạn có thể thay đổi chức năng của giắc cắm âm thanh bằng phần mềm âm thanh. Để cấu hình âm thanh 7.1 kênh, hãy truy cập phần mềm âm thanh để cài đặt âm thanh.Hỗ trợ cho S/PDIF Out", "LAN": "Realtek® 2.5GbE LAN chip (2.5 Gbps/1 Gbps/100 Mbps)", "Mô-đun giao tiếp không dây": "MediaTek Wi-Fi 7 MT7925 (PCB rev. 1.0)- 802.11a, b, g, n, ac, ax, be, hỗ trợ băng tần sóng mang 2,4/5/6 GHz- BLUETOOTH 5.4- Hỗ trợ chuẩn không dây 11be 160MHzRealtek® Wi-Fi 7 RTL8922AE (PCB rev. 1.1)- 802.11a, b, g, n, ac, ax, be, hỗ trợ băng tần sóng mang 2,4/5/6 GHz- BLUETOOTH 5.4- Hỗ trợ chuẩn không dây 11be 160MHz(Tốc độ dữ liệu thực tế có thể thay đổi tùy thuộc vào môi trường và thiết bị.)* Các tính năng của Wi-Fi 7 yêu cầu Windows 11 SV3 để hoạt động bình thường. (Không có trình điều khiển hỗ trợ cho Windows 10.)** Tính khả dụng của các kênh Wi-Fi 7 trên băng tần 6 GHz tùy thuộc vào quy định của từng quốc gia.", "Khe mở rộng": "CPU:- 1 khe cắm PCI Express x16, hỗ trợ PCIe 5.0 và chạy ở x16 (PCIEX16)* Khe cắm PCIEX16 chỉ có thể hỗ trợ card đồ họa hoặc NVMe SSD. Nếu chỉ lắp một card đồ họa, hãy đảm bảo lắp card đó vào khe cắm PCIEX16.Chipset:- 1 khe cắm PCI Express x16, hỗ trợ PCIe 4.0 và chạy ở tốc độ x4 (PCIEX4)", "Giao diện lưu trữ": "CPU:- 1 x đầu nối M.2 (Ổ cắm 3, khóa M, hỗ trợ SSD loại 2580/2280 PCIe 5.0 x4/x2) (M2A_CPU) - 1 x đầu nối M.2 (Ổ cắm 3, khóa M, hỗ trợ SSD loại 2580/2280 PCIe 4.0 x4/x2) (M2B_CPU)Bộ chip:- 1 x đầu nối M.2 (Ổ cắm 3, khóa M, hỗ trợ SSD loại 25110/22110/2580/2280 PCIe 4.0 x4/x2) (M2Q_SB)- 4 x đầu nối SATA 6Gb/sHỗ trợ RAID 0, RAID 1, RAID 5 và RAID 10 cho các thiết bị lưu trữ SSD NVMe Hỗ trợRAID 0, RAID 1, RAID 5 và RAID 10 cho các thiết bị lưu trữ SATA", "USB": "CPU:- 1 x cổng USB4® USB Type-C® ở mặt sauChipset:- 1 x cổng USB Type-C® hỗ trợ USB 3.2 Gen 2, có sẵn thông qua đầu cắm USB bên trong- 1 x cổng USB 3.2 Gen 2 Type-A (màu đỏ) ở mặt sau- 6 x cổng USB 3.2 Gen 1 (4 cổng ở mặt sau, 2 cổng có sẵn thông qua đầu cắm USB bên trong)Chipset+2 Hub USB 2.0:- 8 x cổng USB 2.0/1.1 (4 cổng ở mặt sau, 4 cổng có sẵn thông qua đầu cắm USB bên trong)", "Đầu nối I / O nội bộ": "1 x đầu nối nguồn chính ATX 24 chân2 x đầu nối nguồn ATX 12V 8 chân1 x đầu cắm quạt CPU1 x đầu cắm quạt CPU/bơm làm mát bằng nước3 x đầu cắm quạt hệ thống1 x đầu cắm quạt hệ thống/bơm làm mát bằng nước3 x đầu cắm dải đèn LED RGB Gen2 có thể định địa chỉ1 x đầu cắm dải đèn LED RGB3 x đầu nối M.2 Socket 34 x đầu nối SATA 6Gb/s1 x đầu cắm mặt trước1 x đầu cắm âm thanh mặt trước1 x đầu cắm USB Type-C®, hỗ trợ USB 3.2 Gen 21 x đầu cắm USB 3.2 Gen1 2 x đầu cắm USB 2.0/1.12 x đầu nối card bổ sung Thunderbolt™1 x đầu cắm Trusted Platform Module (Chỉ dành cho mô-đun GC-TPM2.0 SPI/GC-TPM2.0 SPI 2.0/GC-TPM2.0 SPI V2)1 x cổng HDMI (Lưu ý)1 x nút nguồn1 x nút đặt lại1 x Nút Q-Flash Plus1 x jumper reset1 x jumper Clear CMOS(Lưu ý) Hỗ trợ thực tế có thể khác nhau tùy theo CPU.", "Kết nối mặt sau": "1 x Cổng USB4® USB Type-C® (DisplayPort (Lưu ý) )1 x Cổng USB 3.2 Gen 2 Type-A (màu đỏ)4 x Cổng USB 3.2 Gen 14 x Cổng USB 2.0/1.12 x Đầu nối ăng ten (2T2R)1 x DisplayPort (Lưu ý)1 x Cổng RJ-451 x Đầu nối quang S/PDIF Out2 x Giắc cắm âm thanh(Lưu ý) Hỗ trợ thực tế có thể khác nhau tùy theo CPU.", "Bộ điều khiển I / O": "iTE® I / O Controller", "Theo dõi phần cứng": "Phát hiện điện ápPhát hiện nhiệt độ Pháthiện tốc độ quạt Pháthiện lưu lượng nước làm mát Cảnhbáo lỗi quạtKiểm soát tốc độ quạt* Chức năng điều khiển tốc độ quạt (bơm) có được hỗ trợ hay không sẽ tùy thuộc vào quạt (bơm) bạn lắp đặt.", "BIOS": "1 x 256 Mbit flashSử dụng AMI UEFI BIOS được cấp phépPnP 1.0a, DMI 2.7, WfM 2.0, SM BIOS 2.7, ACPI 5.0", "Các tính năng độc đáo": "Hỗ trợ cho Trung tâm điều khiển GIGABYTE (GCC)* Các ứng dụng có sẵn trong GCC có thể khác nhau tùy theo kiểu bo mạch chủ. Các chức năng được hỗ trợ của từng ứng dụng cũng có thể khác nhau tùy thuộc vào thông số kỹ thuật của bo mạch chủ.Hỗ trợ Q-FlashHỗ trợ Q-Flash PlusHỗ trợ Smart Backup", "Gói phần mềm": "Phần mềm quản lý băng thông LAN Norton® Internet Security (phiên bản OEM)", "Hệ điều hành": "Hỗ trợ cho Windows 11 64-bit", "Kích thước bo mạch": "Kích thước Micro ATX; 24,4cm x 24,4cm"}'::jsonb, 'Sản phẩm Mainboard GIGABYTE Z890M AORUS ELITE WIFI7 ICE. Tham khảo chi tiết thông số kỹ thuật bên dưới.', 'ACTIVE', '018f0000-0000-7000-8000-000000000001'),
    ('01a119fe-8e0c-7c60-854c-e87bdb08ae7c', 'Mainboard Asus Z890 AYW Gaming WIFI W DDR5', 'mainboard-asus-z890-ayw-gaming-wifi-w-ddr5', '01a119fe-8dde-71a7-aec0-24231bece465', '01a119fe-8dd1-7e4b-a610-a0a6e479d292', '{"Hãng sản xuất": "Asus", "Model": "Z890 AYW Gaming WIFI W", "Chipset": "Intel® Z890 Chipset", "CPU": "Hỗ trợ Intel® Core™ Ultra Processors (Series 2), LGA1851. Hỗ trợ Intel® Turbo Boost Technology 2.0 và Intel® Turbo Boost Max Technology 3.0 (tùy thuộc vào loại CPU).", "Bộ nhớ (RAM)": "4 khe DIMM, tối đa 192GB DDR5, hỗ trợ tốc độ lên đến 9066+ MT/s (OC), Non-ECC, Un-buffered, CUDIMM, kiến trúc Dual Channel, hỗ trợ Intel® Extreme Memory Profile (XMP) và ASUS Enhanced Memory Profile III (AEMPIII).", "Đồ họa": "1 cổng DisplayPort (hỗ trợ tối đa 4K@60Hz với DisplayPort 1.4), 1 cổng USB 20Gbps Type-C hỗ trợ DisplayPort video output (hỗ trợ tối đa 4K@120Hz theo DisplayPort 1.4).", "Khe cắm mở rộng": "1 khe PCIe 5.0 x16, 2 khe PCIe 4.0 x16 (hỗ trợ chế độ x4), 1 khe PCIe 4.0 x16 (hỗ trợ chế độ x1).", "Âm thanh": "Realtek 7.1 Surround Sound High Definition Audio CODEC, hỗ trợ phát lại lên đến 24-Bit/192 kHz, tính năng che chắn âm thanh, tụ điện âm thanh cao cấp, các lớp PCB âm thanh chuyên dụng.", "Lưu trữ": "4 khe M.2 (hỗ trợ PCIe 5.0 x4, PCIe 4.0 x4 và SATA) và 4 cổng SATA 6Gb/s. Hỗ trợ Intel® Rapid Storage Technology cho PCIe RAID 0/1/5/10 và SATA RAID 0/1/5/10.", "USB": "Phía sau: 1 cổng USB 20Gbps Type-C với DP Alt mode, 3 cổng USB 10Gbps Type-A, 4 cổng USB 2.0 Type-A. Phía trước: 1 đầu nối USB 20Gbps Type-C hỗ trợ sạc nhanh PD 30W, 2 đầu nối USB 5Gbps, 2 đầu nối USB 2.0.", "Cổng LAN": "1 cổng Realtek 2.5Gb Ethernet, ASUS LANGuard.", "Wi-Fi và Bluetooth": "Wi-Fi 6 (802.11 a/b/g/n/ac/ax), hỗ trợ băng tần 2.4/5GHz, Bluetooth v5.3.", "Tính năng đèn LED": "Aura Sync, Addressable Gen 2 headers.", "Hệ điều hành hỗ trợ": "Windows 11 (22H2 trở lên), Windows 10 64-bit (21H2 trở lên).", "Kích thước (Form Factor)": "ATX Form Factor, 12 inch x 9.6 inch (30.5 cm x 24.4 cm).", "Kết nối I/O nội bộ": "1 x 4-pin CPU Fan header, 1 x 4-pin CPU OPT Fan header, 1 x 4-pin AIO Pump header, 4 x 4-pin Chassis Fan headers, 1 x 24-pin Main Power connector, 2 x 8-pin +12V CPU Power connectors, 4 x M.2 slots (Key M), 4 x SATA 6Gb/s ports, 1 x USB 20Gbps connector (supports USB Type-C® with up to 30W PD/PPS Fast-charge ), 2 x USB 5Gbps headers, 2 x USB 2.0 headers, 3 x Addressable Gen2 headers, 1 x Clear CMOS header, 1 x COM Port header, 1 x Front Panel Audio header (F_AUDIO), 1 x S/PDIF Out header, 1 x SPI TPM header (14-1 pin), 1 x 10-1 pin Front Panel System header, 1 x Thunderbolt™ (USB4®) Header.", "Kết nối I/O phía sau": "1 x USB 20Gbps port (1 x USB Type-C® with DP Alt mode), 3 x USB 10Gbps ports (3 x Type-A), 4 x USB 2.0 ports (4 x Type-A), 1 x DisplayPort, 1 x Wi-Fi module, 1 x Realtek 2.5Gb Ethernet port, 3 x Audio jacks, 1 x BIOS FlashBack™ button."}'::jsonb, 'Sản phẩm Mainboard Asus Z890 AYW Gaming WIFI W DDR5. Tham khảo chi tiết thông số kỹ thuật bên dưới.', 'ACTIVE', '018f0000-0000-7000-8000-000000000001'),
